/*
 * Discourse 的“跳转到…”（按键 #）：输入帖子编号。核心没有这个
 * 窗口；时间线只能拖动。（Discourse 的按日期跳转选项不在其中：
 * Flarum 的 API 无法按日期查找帖子。）
 */

import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import Stream from 'flarum/common/utils/Stream';
import { t } from '../../utils/settings';
export default class JumpToPostModal extends FormModal {
  number = Stream('');
  className() {
    return 'LcoyJumpModal Modal--small';
  }
  title() {
    return t('gaps.jump.title');
  }
  content() {
    const count = this.attrs.stream?.count?.() || 0;
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form-group LcoyJumpModal-number"
    }, m("label", {
      for: "lcoy-jump-number"
    }, t('gaps.jump.post_label')), m("div", {
      className: "LcoyJumpModal-row"
    }, m("input", {
      id: "lcoy-jump-number",
      className: "FormControl",
      type: "number",
      min: "1",
      max: count || undefined,
      bidi: this.number,
      placeholder: "#"
    }), m("span", {
      className: "LcoyJumpModal-of"
    }, t('gaps.jump.of', {
      count
    })))), m("div", {
      className: "Form-group"
    }, m(Button, {
      className: "Button Button--primary Button--block",
      type: "submit"
    }, t('gaps.jump.submit'))));
  }
  onsubmit(event) {
    event.preventDefault();
    const stream = this.attrs.stream;
    const number = parseInt(this.number(), 10);
    this.hide();
    if (number > 0) stream.goToNumber(number);
  }
}
flarum.reg.add('lcoy-roselle', 'forum/gaps/topic/JumpToPostModal', JumpToPostModal);